            if($old){if((int)$old['issuer_id']!==$issuer||(int)$old['task_id']!==$id||(int)$old['actor_id']!==$actor||!hash_equals($inputHash,$old['input_hash']))throw new DomainException('company_task_billing_conflict');$this->origin($issuer,$id,(int)$old['id']);return (int)$old['id'];}
