        $claim=$this->billingTx($issuer,$actor,function()use($issuer,$actor,$id,$origin){$task=$this->task($issuer,$id);$link=$this->link($issuer,$id);if(!$link||(int)$link['origin_id']!==$origin)throw new DomainException('company_task_billing_stale');if($link['state']==='converted'){$this->confirmedInvoice($issuer,$id,$link);return $link;}if(!in_array($link['state'],['ready','converting'],true))throw new DomainException('company_task_billing_not_billable');if($link['state']==='converting'&&(int)$link['conversion_actor_id']!==$actor)throw new DomainException('company_task_billing_conflict');IssuerStorage::query($this->db,'UPDATE '.$this->prefix.'company_task_billing_links SET state=?,conversion_actor_id=?,updated_at=? WHERE task_id=? AND issuer_id=?',['converting',$actor,gmdate('Y-m-d H:i:s'),$id,$issuer]);$this->portalState($issuer,$id,'unbilled','converting');$this->guard($issuer,$actor,$id,$origin);$this->billingAudit($issuer,$actor,$id,'company_task_conversion_claimed',$origin);$this->guard($issuer,$actor,$id,$origin);return $this->link($issuer,$id);});
