        return$this->billingReadTx($issuer,$actor,function()use($issuer,$actor,$id){
            $task=$this->task($issuer,$id);$link=$this->link($issuer,$id);
            if($link===null)return['available'=>false,'reason'=>'not_declared','task_id'=>$id,'task_revision'=>(int)$task['revision']];
