            if($link['state']!=='ready')return['available'=>false,'reason'=>$link['state'],'task_id'=>$id,'task_revision'=>(int)$task['revision']];
            $receipt=$this->rows('SELECT issuer_id,invoice_id FROM '.$this->prefix.'company_invoice_requests WHERE request_key=? FOR UPDATE',[self::canonicalKey($issuer,$id)]);if($receipt)throw new RuntimeException('issuer_task_billing_unconfirmed');
