            $source=$this->source($issuer,$id);$source['project_name']=$captured['project_name'];$source['billing_profile']=$captured['billing_profile'];
            if(!hash_equals($origin['source_hash'],self::hash($source)))throw new DomainException('company_task_billing_stale');$this->references($issuer,$actor,$source);
            if(isset($captured['billing_profile']['project_rate_origin'])){$rate=$captured['billing_profile']['project_rate_origin'];$current=(new CompanyProjectBillingRates($this->db,$this->prefix))->inOwned($issuer,$actor,(int)$task['project_id'],$rate['id']);if($current['payload']!==$rate['payload']||!hash_equals($current['payload_hash'],$rate['payload_hash']))throw new DomainException('company_project_rate_stale');}
            $payload=$this->decode($origin['payload_json']);$context=$this->decode($origin['context_json']);$this->assertOrigin($issuer,$actor,$payload,$origin['origin_hash'],$context);
            if($this->task($issuer,$id)!==$task||$this->link($issuer,$id)!==$link||$this->origin($issuer,$id,(int)$link['origin_id'])!==$origin)throw new DomainException('company_task_billing_stale');
