    public function status($issuer,$actor,$id):?array
    {return$this->statusProjection($issuer,$actor,$id,false);}
    /** Verified financial evidence only; this method grants no preparation/conversion authority. */
    public function readStatus($issuer,$actor,$id){return$this->statusProjection($issuer,$actor,$id,true);}
