        $work=function()use($issuer,$actor,$id){$this->task($issuer,$id);$r=$this->link($issuer,$id);if(!$r)return null;$o=$this->origin($issuer,$id,(int)$r['origin_id']);$source=$this->decode($o['source_json']);$payload=$this->decode($o['payload_json']);$receipt=$this->rows('SELECT issuer_id,invoice_id FROM '.$this->prefix.'company_invoice_requests WHERE request_key=? FOR UPDATE',[self::canonicalKey($issuer,$id)])[0]??null;if($receipt&&(int)$receipt['issuer_id']!==$issuer)throw new RuntimeException('issuer_task_billing_unconfirmed');$invoiceCurrent=null;if($r['state']==='converted'||$receipt){if(!in_array($r['state'],['converting','converted'],true))throw new RuntimeException('issuer_task_billing_unconfirmed');$confirmed=$r;if($r['state']==='converting'){if($r['invoice_id']!==null)throw new RuntimeException('issuer_billing_invoice_unconfirmed');$confirmed['invoice_id']=$receipt['invoice_id'];}$this->confirmedInvoice($issuer,$id,$confirmed);$invoiceCurrent=(new CompanyBillingInvoiceLifecycle($this->db,$this->prefix))->inOwned($issuer,$actor,(int)$confirmed['invoice_id'],self::canonicalKey($issuer,$id),(int)$r['conversion_actor_id'],$payload);}
